async function spTestKey() {
  const key = String(spS().key || '').trim(); if (!key) return toast('Сначала вставь ключ', 'lyrics');
  toast('Проверяю ключ…', 'lyrics');
  const r = await pulse.spicy.lyrics({ id: 'sp:1QV6tiMFM6fSOKOGLMHYYg', title: 'test' }, key).catch((e) => ({ error: String(e.message || e) }));
  toast(r && r.body ? 'Ключ работает — Spicy Lyrics отвечает' : r && r.error === 'badkey' ? 'Spicy Lyrics не принял ключ' : r && r.error === 'limit' ? 'Лимит запросов — попробуй позже' : 'Не получилось: ' + ((r && (r.status || r.error)) || 'нет ответа'), 'lyrics');
}
document.addEventListener('click', (e) => { const b = e.target.closest && e.target.closest('[data-spc="test"]'); if (b) { e.preventDefault(); spTestKey(); } });
